import{_ as a,a as t,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第三册：培养技能 · Lesson 33 A day to remember","description":"学习 否定副词前置倒装，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第三册：培养技能 · Lesson 33 A day to remember","description":"学习 否定副词前置倒装，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第3册课时","summary":"学习 否定副词前置倒装，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第三册：培养技能 · Lesson 32 A lost ship","link":"/life/english/new-concept/book-3/unit-02/lesson-032"},"next":{"text":"第三册：培养技能 · Lesson 34 A happy discovery","link":"/life/english/new-concept/book-3/unit-02/lesson-034"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第三册：培养技能 · Lesson 32 A lost ship","link":"/life/english/new-concept/book-3/unit-02/lesson-032"},"next":{"text":"第三册：培养技能 · Lesson 34 A happy discovery","link":"/life/english/new-concept/book-3/unit-02/lesson-034"}},"headers":[],"relativePath":"life/english/new-concept/book-3/unit-02/lesson-033.md","filePath":"life/english/new-concept/book-3/unit-02/lesson-033.md"}'),i={name:"life/english/new-concept/book-3/unit-02/lesson-033.md"};function r(l,e,s,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第三册-培养技能-·-lesson-33-a-day-to-remember" tabindex="-1">第三册：培养技能 · Lesson 33 A day to remember <a class="header-anchor" href="#第三册-培养技能-·-lesson-33-a-day-to-remember" aria-label="Permalink to &quot;第三册：培养技能 · Lesson 33 A day to remember&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-3/contents">本册目录</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元 2</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕难忘的一天组织时间、转折和感受，避免只是流水账。学习把最出人意料的经历放在焦点，并用倒装表达强烈但有依据的感受。写作时先确保普通语序正确，再使用倒装，防止为了书面感而让主语、助动词和谓语失去一致。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>memorable</td><td>/ˈmemərəbl/</td><td>adj.</td><td>难忘的</td><td>a memorable day</td></tr><tr><td>delay</td><td>/dɪˈleɪ/</td><td>n.</td><td>延误</td><td>an unexpected delay</td></tr><tr><td>relief</td><td>/rɪˈliːf/</td><td>n.</td><td>宽慰</td><td>a sense of relief</td></tr><tr><td>incident</td><td>/ˈɪnsɪdənt/</td><td>n.</td><td>事件</td><td>a minor incident</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>to one&#39;s relief — 令某人宽慰的是</li><li>not until — 直到……才，注意倒装位置</li></ul><h2 id="语法讲解-否定副词前置倒装" tabindex="-1">语法讲解：否定副词前置倒装 <a class="header-anchor" href="#语法讲解-否定副词前置倒装" aria-label="Permalink to &quot;语法讲解：否定副词前置倒装&quot;">​</a></h2><p>never、rarely、seldom 等否定或近否定副词放在句首时，通常触发部分倒装，即助动词置于主语前。原句没有助动词时，根据时态加入 do、does 或 did，实义动词恢复原形。Never had I seen ... 把完成时的 had 前移。倒装主要用于较正式或强调性表达，不必每段都使用。not until 引导状语置前时，倒装发生在主句而非 until 从句；若否定词不位于句首，通常保持普通语序。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>Never had I seen the station so quiet before that morning.</p></blockquote><p>在那个早晨之前，我从未见过车站如此安静。</p><p>never 前置使 had 提到 I 前；seen 保持过去分词，before that morning 给出过去参照点。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>Never I saw ... 缺少倒装；一般过去时应写 Never did I see ...，不能写 did I saw。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>先读普通语序 I have rarely travelled，再读 Rarely have I travelled，比较 have 的位置，不要在倒装中遗失 I。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>Rarely have I travelled through such dense fog. The bus stopped beside a closed bakery for nearly an hour. When sunlight finally reached the windows, everyone cheered.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句难忘经历，包含一个倒装句和具体细节。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>倒装给整体感受，后两句提供可见情节支持感受。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>改写：I rarely travel without a notebook.（Rarely 开头）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Rarely do I travel without a notebook.</p><p><strong>解析：</strong> 补入 do 并把主语置于其后。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>例句里的 had 为什么在 I 前？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 句首 never 触发部分倒装。</p><p><strong>解析：</strong> 倒装移动助动词而非过去分词。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>改正：Not until noon did she arrived.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Not until noon did she arrive.</p><p><strong>解析：</strong> did 后实义动词恢复原形。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：否定副词前置倒装。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-3/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-3/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-3/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-3/unit-02/lesson-032">上一课</a> · <a href="/life/english/new-concept/book-3/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-3/unit-02/lesson-034">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
